node -e "
const fs = require('fs');
const Database = require('/tmp/sqlite/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// ---------------------------------------------------------------
// Load all relevant data (mirrors ENV_CLASS.__init__)
// ---------------------------------------------------------------
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get('ORD-5B048F');
const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all('ORD-5B048F');
const customer = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.customer_id);

const productIds = items.map(i => i.product_id);
const products = {};
db.prepare('SELECT * FROM products WHERE product_id IN (' + productIds.map(() => '?').join(',') + ')')
  .all(...productIds)
  .forEach(p => { products[p.product_id] = p; });

// ---------------------------------------------------------------
// Policy constants (from policies.py)
// ---------------------------------------------------------------
const RETURN_WINDOWS = { electronics: 15, clothing: 30, kitchen: 30, books: 14, accessories: 30 };
const TIER_RETURN_EXTENSION = { standard: 0, silver: 0, gold: 15, platinum: 15 };
const PRIME_RETURN_EXTENSION = 15;
const RESTOCKING_FEE_PCT = 15;
const FREE_SHIPPING_THRESHOLD = 100;
const STANDARD_SHIPPING_COST = 8;
const BULK_DISCOUNT_THRESHOLD = 3;
const BULK_CLAWBACK_PER_ITEM = 5;
const REPEAT_CATEGORY_SURCHARGE = 5;
const PAID_RETURN_SHIPPING_THRESHOLD = 50;
const PAID_RETURN_SHIPPING_FEE = 8;
const RESTOCKING_DISCOUNT_BY_TIER = { gold: 0.50, silver: 0.25 };
const NOW = '2026-06-15T10:00:00';  // DEFAULT_NOW from domain_meta.py

// ---------------------------------------------------------------
// Process each item (mirrors env.process_return preview logic)
// ---------------------------------------------------------------
const results = [];

for (const item of items) {
  const product = products[item.product_id];
  const reason = item.return_reason || 'changed_mind';
  const membershipTier = customer.loyalty_tier;
  const hasPrime = !!customer.has_prime_shipping;

  // Already returned/exchanged/cancelled?
  if (['returned', 'exchanged', 'cancelled'].includes(item.item_status)) {
    results.push({
      item_id: item.oi_id,
      product_name: product.name,
      status: 'already_processed',
      item_status: item.item_status,
      return_reason: item.return_reason,
      refund_amount: item.refund_amount,
      refund_method: item.refund_method,
      restocking_fee: item.restocking_fee,
      return_label_issued: !!item.return_label_issued,
      reason: 'Item already ' + item.item_status
    });
    continue;
  }

  // Not delivered?
  if (!order.delivery_date) {
    results.push({
      item_id: item.oi_id,
      product_name: product.name,
      status: 'rejected',
      reason: 'Item not yet delivered — use cancellation instead'
    });
    continue;
  }

  // Eligibility: check return window
  const isProductFault = ['defective', 'wrong_item', 'damaged_in_transit'].includes(reason);
  const baseWindow = RETURN_WINDOWS[product.category] || 30;
  const tierExt = TIER_RETURN_EXTENSION[membershipTier] || 0;
  const primeExt = hasPrime ? PRIME_RETURN_EXTENSION : 0;
  const effectiveWindow = baseWindow + tierExt + primeExt;

  const deliveryDt = new Date(order.delivery_date);
  const nowDt = new Date(NOW);
  const daysSinceDelivery = Math.floor((nowDt - deliveryDt) / (1000 * 60 * 60 * 24));

  let eligible = true;
  let eligibilityReason = '';
  let storeCreditOnly = false;
  let freeReturnShipping = false;

  if (isProductFault) {
    eligible = true;
    eligibilityReason = 'Return eligible: ' + reason + ' (no window restriction)';
    freeReturnShipping = true;
  } else if (daysSinceDelivery > effectiveWindow) {
    const storeCreditWindow = effectiveWindow + 15;
    if (daysSinceDelivery <= storeCreditWindow) {
      eligible = true;
      storeCreditOnly = true;
      eligibilityReason = 'Outside ' + effectiveWindow + '-day return window but within ' + storeCreditWindow + '-day store credit window';
    } else {
      eligible = false;
      eligibilityReason = 'Outside ' + storeCreditWindow + '-day return window (' + daysSinceDelivery + ' days since delivery)';
    }
  } else {
    eligible = true;
    eligibilityReason = 'Within ' + effectiveWindow + '-day return window (' + daysSinceDelivery + ' days since delivery)';
  }

  if (!eligible) {
    results.push({
      item_id: item.oi_id,
      product_name: product.name,
      status: 'rejected',
      reason: eligibilityReason
    });
    continue;
  }

  // Refund calculation
  let restockingFee = 0;
  if (product.category === 'electronics' && reason === 'changed_mind') {
    restockingFee = Math.floor(item.unit_price * RESTOCKING_FEE_PCT / 100);
    if (membershipTier === 'platinum') restockingFee = 0;
  }

  let discountAdj = 0;
  if (order.discount_code && order.discount_amount > 0 && order.subtotal > 0) {
    discountAdj = Math.floor(order.discount_amount * item.unit_price / order.subtotal);
  }

  const baseRefund = item.unit_price - restockingFee - discountAdj;
  const refundMethod = storeCreditOnly ? 'store_credit' : 'original_payment';
  const shippingRefund = isProductFault;

  // Free-shipping clawback
  const originalFreeShipping = order.subtotal >= FREE_SHIPPING_THRESHOLD;
  const remainingItems = items.filter(i => i.oi_id !== item.oi_id && !['returned', 'cancelled', 'exchanged'].includes(i.item_status));
  const remainingSubtotal = remainingItems.reduce((s, i) => s + i.unit_price, 0);
  let shippingClawback = 0;
  if (!isProductFault && originalFreeShipping && remainingSubtotal < FREE_SHIPPING_THRESHOLD) {
    shippingClawback = STANDARD_SHIPPING_COST;
  }

  // Bulk clawback
  let bulkClawback = 0;
  if (order.discount_code && order.discount_amount > 0 && items.length >= BULK_DISCOUNT_THRESHOLD) {
    if (remainingItems.length < BULK_DISCOUNT_THRESHOLD) {
      bulkClawback = BULK_CLAWBACK_PER_ITEM * remainingItems.length;
    }
  }

  // Repeat-category surcharge
  const alreadyReturnedCats = items
    .filter(i => i.oi_id !== item.oi_id && i.item_status === 'returned')
    .map(i => products[i.product_id]?.category)
    .filter(Boolean);
  const sameCatCount = alreadyReturnedCats.filter(c => c === product.category).length;
  const repeatSurcharge = sameCatCount > 0 ? REPEAT_CATEGORY_SURCHARGE : 0;

  // Paid return shipping
  let paidReturnShippingFee = 0;
  if (!isProductFault && order.subtotal < PAID_RETURN_SHIPPING_THRESHOLD) {
    paidReturnShippingFee = PAID_RETURN_SHIPPING_FEE;
  }

  // Restocking discount (Gold 50%, Silver 25%)
  let restockingDiscount = 0;
  const discountPct = RESTOCKING_DISCOUNT_BY_TIER[membershipTier] || 0;
  if (membershipTier !== 'platinum' && discountPct > 0) {
    restockingDiscount = Math.floor(restockingFee * discountPct);
  }

  const finalRefund = Math.max(0,
    baseRefund - shippingClawback - bulkClawback - repeatSurcharge - paidReturnShippingFee + restockingDiscount
  );

  results.push({
    item_id: item.oi_id,
    product_name: product.name,
    product_id: item.product_id,
