const TIER_RETURN_EXTENSION = { standard: 0, silver: 0, gold: 15, platinum: 15 };
const PRIME_RETURN_EXTENSION = 15;

// Get all delivered orders with their items
const orders = db.prepare(\`
  SELECT o.order_id, o.customer_id, o.order_date, o.delivery_date, o.subtotal,
         o.discount_code, o.discount_amount, o.shipping_status,
         u.name AS customer_name, u.loyalty_tier, u.has_prime_shipping
  FROM orders o
  JOIN users u ON o.customer_id = u.user_id
  WHERE o.shipping_status = 'delivered'
  ORDER BY o.order_id
\`).all();

const results = [];

for (const order of orders) {
  const items = db.prepare(\`
    SELECT oi.oi_id, oi.product_id, oi.unit_price, oi.item_status, oi.return_reason,
           p.name AS product_name, p.category
    FROM order_items oi
    JOIN products p ON oi.product_id = p.product_id
    WHERE oi.order_id = ?
  \`).all(order.order_id);

  // Filter to items not yet returned/exchanged/cancelled
  const eligible = items.filter(i => !['returned', 'exchanged', 'cancelled'].includes(i.item_status));

  if (eligible.length === 0) continue;

  // Check return window for each eligible item
  const deliveryDt = new Date(order.delivery_date);
  const daysSinceDelivery = Math.floor((nowDt - deliveryDt) / (1000 * 60 * 60 * 24));

  const returnableItems = [];
  for (const item of eligible) {
