    const tierExt = TIER_RETURN_EXTENSION[order.loyalty_tier] || 0;
    const primeExt = order.has_prime_shipping ? PRIME_RETURN_EXTENSION : 0;
    const effectiveWindow = baseWindow + tierExt + primeExt;
    const storeCreditWindow = effectiveWindow + 15;

    let windowStatus;
    if (daysSinceDelivery <= effectiveWindow) {
      windowStatus = 'within return window (' + effectiveWindow + 'd)';
    } else if (daysSinceDelivery <= storeCreditWindow) {
      windowStatus = 'store credit only (' + storeCreditWindow + 'd)';
    } else {
      windowStatus = 'EXPIRED';
    }

    if (windowStatus !== 'EXPIRED') {
      returnableItems.push({
        item_id: item.oi_id,
        product_name: item.product_name,
        category: item.category,
        unit_price: item.unit_price,
        item_status: item.item_status,
        window_status: windowStatus
      });
    }
  }

  if (returnableItems.length > 0) {
    results.push({
      order_id: order.order_id,
      customer_name: order.customer_name,
      membership_tier: order.loyalty_tier,
      prime: !!order.has_prime_shipping,
      delivery_date: order.delivery_date,
      days_since_delivery: daysSinceDelivery,
