node -e "
const fs = require('fs');
const Database = require('/tmp/sqlite/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// ---------------------------------------------------------------
// Load data
// ---------------------------------------------------------------
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get('ORD-66CC25');
const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all('ORD-66CC25');
const customer = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.customer_id);

const productIds = items.map(i => i.product_id);
const products = {};
db.prepare('SELECT * FROM products WHERE product_id IN (' + productIds.map(()=>'?').join(',') + ')')
  .all(...productIds)
  .forEach(p => { products[p.product_id] = p; });

// ---------------------------------------------------------------
// Policy constants (policies.py)
// ---------------------------------------------------------------
const RETURN_WINDOWS     = { electronics: 15, clothing: 30, kitchen: 30, books: 14, accessories: 30 };
const TIER_RETURN_EXT    = { standard: 0, silver: 0, gold: 15, platinum: 15 };
const PRIME_RETURN_EXT   = 15;
const RESTOCKING_FEE_PCT = 15;
const FREE_SHIP_THRESH   = 100;
const STD_SHIP_COST      = 8;
const BULK_THRESH        = 3;
const BULK_CLAWBACK_PER  = 5;
const REPEAT_SURCHARGE   = 5;
const PAID_RET_SHIP_THR  = 50;
const PAID_RET_SHIP_FEE  = 8;
const RESTOCK_DISC_TIER  = { gold: 0.50, silver: 0.25 };
const NOW = '2026-06-15T10:00:00';

// ---------------------------------------------------------------
// Process each eligible item (mirrors env.process_return preview)
// ---------------------------------------------------------------
const membershipTier = customer.loyalty_tier;
const hasPrime = !!customer.has_prime_shipping;
const results = [];

for (const item of items) {
  const product = products[item.product_id];
  const reason = 'changed_mind';  // default reason for process_return

  // Skip already-processed items
  if (['returned', 'exchanged', 'cancelled'].includes(item.item_status)) {
    results.push({
      item_id: item.oi_id,
      product_name: product.name,
      product_id: item.product_id,
      category: product.category,
      unit_price: item.unit_price,
      status: 'already_processed',
      item_status: item.item_status,
      reason: 'Item already ' + item.item_status
    });
    continue;
  }

  // Delivery check
  if (!order.delivery_date) {
    results.push({
      item_id: item.oi_id, product_name: product.name, product_id: item.product_id,
      category: product.category, unit_price: item.unit_price,
      status: 'rejected', reason: 'Item not yet delivered — use cancellation instead'
    });
    continue;
  }

  // Return window eligibility
  const isProductFault = ['defective','wrong_item','damaged_in_transit'].includes(reason);
  const baseWindow = RETURN_WINDOWS[product.category] || 30;
  const tierExt = TIER_RETURN_EXT[membershipTier] || 0;
  const primeExt = hasPrime ? PRIME_RETURN_EXT : 0;
  const effectiveWindow = baseWindow + tierExt + primeExt;

  const deliveryDt = new Date(order.delivery_date);
  const nowDt = new Date(NOW);
  const daysSinceDelivery = Math.floor((nowDt - deliveryDt) / (1000*60*60*24));

  let eligible = true, eligReason = '', storeCreditOnly = false, freeReturnShipping = false;

  if (isProductFault) {
    eligReason = 'Return eligible: ' + reason + ' (no window restriction)';
    freeReturnShipping = true;
  } else if (daysSinceDelivery > effectiveWindow) {
    const scWindow = effectiveWindow + 15;
    if (daysSinceDelivery <= scWindow) {
      storeCreditOnly = true;
      eligReason = 'Outside ' + effectiveWindow + '-day return window but within ' + scWindow + '-day store credit window';
    } else {
      eligible = false;
      eligReason = 'Outside ' + scWindow + '-day return window (' + daysSinceDelivery + ' days since delivery)';
    }
  } else {
    eligReason = 'Within ' + effectiveWindow + '-day return window (' + daysSinceDelivery + ' days since delivery)';
  }

  if (!eligible) {
    results.push({
      item_id: item.oi_id, product_name: product.name, product_id: item.product_id,
      category: product.category, unit_price: item.unit_price,
      status: 'rejected', reason: eligReason
    });
    continue;
  }

  // --- Refund calculation ---
  // Restocking fee (15% for opened electronics + changed_mind)
  let restockingFee = 0;
  if (product.category === 'electronics' && reason === 'changed_mind') {
    restockingFee = Math.floor(item.unit_price * RESTOCKING_FEE_PCT / 100);
    if (membershipTier === 'platinum') restockingFee = 0;
  }

  // Promo redistribution
  let discountAdj = 0;
  if (order.discount_code && order.discount_amount > 0 && order.subtotal > 0) {
    discountAdj = Math.floor(order.discount_amount * item.unit_price / order.subtotal);
  }

  const baseRefund = item.unit_price - restockingFee - discountAdj;
  const refundMethod = storeCreditOnly ? 'store_credit' : 'original_payment';
  const shippingRefund = isProductFault;

  // Free-shipping clawback
  const origFreeShip = order.subtotal >= FREE_SHIP_THRESH;
  const remainingItems = items.filter(i =>
    i.oi_id !== item.oi_id && !['returned','cancelled','exchanged'].includes(i.item_status)
  );
  const remainingSubtotal = remainingItems.reduce((s,i) => s + i.unit_price, 0);
  let shippingClawback = 0;
  if (!isProductFault && origFreeShip && remainingSubtotal < FREE_SHIP_THRESH) {
    shippingClawback = STD_SHIP_COST;
  }

  // Bulk-discount clawback
  let bulkClawback = 0;
  if (order.discount_code && order.discount_amount > 0 && items.length >= BULK_THRESH) {
    if (remainingItems.length < BULK_THRESH) {
      bulkClawback = BULK_CLAWBACK_PER * remainingItems.length;
    }
  }

  // Repeat-category surcharge
  const alreadyRetCats = items
    .filter(i => i.oi_id !== item.oi_id && i.item_status === 'returned')
    .map(i => products[i.product_id]?.category).filter(Boolean);
  const sameCatCount = alreadyRetCats.filter(c => c === product.category).length;
  const repeatSurcharge = sameCatCount > 0 ? REPEAT_SURCHARGE : 0;

  // Paid return shipping (<\$50 subtotal, non-fault)
  let paidRetShipFee = 0;
  if (!isProductFault && order.subtotal < PAID_RET_SHIP_THR) {
    paidRetShipFee = PAID_RET_SHIP_FEE;
  }

  // Tier restocking discount (Gold 50%, Silver 25%)
  let restockDiscount = 0;
  const rdPct = RESTOCK_DISC_TIER[membershipTier] || 0;
  if (membershipTier !== 'platinum' && rdPct > 0) {
    restockDiscount = Math.floor(restockingFee * rdPct);
  }

  const finalRefund = Math.max(0,
    baseRefund - shippingClawback - bulkClawback - repeatSurcharge - paidRetShipFee + restockDiscount
  );

  results.push({
    item_id: item.oi_id,
    product_name: product.name,
    product_id: item.product_id,
    category: product.category,
    unit_price: item.unit_price,
    status: 'preview',
    return_eligible: true,
    reason: reason,
    eligibility_reason: eligReason,
    effective_return_window_days: effectiveWindow,
    days_since_delivery: daysSinceDelivery,
    refund_amount: finalRefund,
    refund_method: refundMethod,
    restocking_fee: restockingFee,
    restocking_discount: restockDiscount,
    discount_adjustment: discountAdj,
    free_return_shipping: freeReturnShipping,
    shipping_refund: shippingRefund,
    shipping_clawback: shippingClawback,
    bulk_clawback: bulkClawback,
    repeat_surcharge: repeatSurcharge,
    paid_return_shipping_fee: paidRetShipFee,
    store_credit_only: storeCreditOnly
  });
}

// ---------------------------------------------------------------
// Build output (mirrors CLI cmd_call format)
// ---------------------------------------------------------------
const output = {
  tool: 'process_return',
  is_write: true,
  context: {
    cs_policies_checked: ['return']
  },
  order_id: 'ORD-66CC25',
  customer: {
    customer_id: customer.user_id,
    name: customer.name,
    membership_tier: customer.loyalty_tier,
    has_prime_shipping: !!customer.has_prime_shipping
  },
  order_summary: {
    order_date: order.order_date,
    status: order.status,
    shipping_status: order.shipping_status,
    delivery_date: order.delivery_date,
    subtotal: order.subtotal,
    discount_code: order.discount_code,
    discount_amount: order.discount_amount,
    total_paid: order.total_paid,
    shipping_cost: order.shipping_cost,
    payment_method: order.payment_method,
    is_gift: !!order.is_gift
  },
  items: results
};

const outputStr = JSON.stringify(output, null, 2);
console.log(outputStr);

// Save
fs.mkdirSync('/workspace/outputs', { recursive: true });
fs.writeFileSync('/workspace/outputs/return_output.txt', outputStr);

// Update session.json to persist cs_policies_checked
const sessionDir = '/workspace/skills/state-customer-support/.state';
fs.mkdirSync(sessionDir, { recursive: true });
const session = {
  '_policies_checked': { '__set__': ['return'] },
  '_previewed': {
    'return': { '__set__': results.filter(r => r.status === 'preview').map(r => r.item_id) },
    'refund': { '__set__': [] },
    'cancel': { '__set__': [] },
    'exchange': { '__set__': [] },
    'warranty_claim': { '__set__': [] }
  },
  '_previewed_refunds': {}
};
fs.writeFileSync(sessionDir + '/session.json', JSON.stringify(session, null, 2));
"

